                            self.unit_test.assertTrue(isinstance(quantizer, qi.BaseKerasTrainableQuantizer))"", ""found"": true, ""signature"": """", ""callsite_slice"": """", ""evidence_slice"": """", ""match_score"": 0, ""confidence"": 0.0, ""confidence_label"": """"}, {""method_name"": ""QuantizationAwareTrainingQuantizersTest"", ""path"": ""tests/keras_tests/feature_networks_tests/feature_networks/qat/qat_test.py"", ""class_name"": null, ""start_line"": 91, ""end_line"": 119, ""source"": ""class QuantizationAwareTrainingQuantizersTest(QuantizationAwareTrainingTest):

    def __init__(self, unit_test, weight_bits=8, activation_bits=4, finalize=False):
        super().__init__(unit_test, layers.DepthwiseConv2D(5, activation='relu'),
                         weight_bits=weight_bits, activation_bits=activation_bits, finalize=finalize)

    def create_networks(self):
        inputs = layers.Input(shape=self.get_input_shapes()[0][1:])
        outputs = self.layer(inputs)
        w = np.arange(5 * 5 * 3, dtype=np.float32).reshape((3, 5, 5, 1)).transpose((1, 2, 0, 3))
