        return out

    def expand(self):
        out = Matrix(self.lines,self.cols,map(lambda i: i.expand(), self.mat))
        return out

    def combine(self):
        out = Matrix(self.lines,self.cols,map(lambda i: i.combine(),self.mat))
        return out

    def subs(self, *args):
        out = Matrix(self.lines,self.cols,map(lambda i: i.subs(*args),self.mat))
        return out

