    def __init__(self, uri=None, name=None, tracks=None):
        self._uri = uri
        self._name = name
        self._tracks = tracks or []

    @property
    def uri(self):
        return self._uri

    @property
    def name(self):
        return self._name

    @property
    def tracks(self):
        return copy(self._tracks)

    @property
    def length(self):
        return len(self._tracks)

    def mpd_format(self, start=0, end=None):
        if end is None:
            end = self.length
        tracks = []
