            self.meldType = self._getMeldType()
            self.name = meldName(self.meldType)
        return property(**locals())"", ""found"": true, ""signature"": """", ""callsite_slice"": """", ""evidence_slice"": """", ""match_score"": 0, ""confidence"": 0.0, ""confidence_label"": """"}, {""method_name"": ""remove"", ""path"": ""src/board.py"", ""class_name"": ""HandBoard"", ""start_line"": 678, ""end_line"": 701, ""source"": ""def remove(self, data):
